{"action":"write_file","path":"solution.py","content":"from money import amount, display
def summary(lines, discount):
    if discount < 0 or discount > 1:
        raise ValueError('Discount must be between 0 and 1')
    result = {}
    for line in lines:
        if float(line['quantity']) < 0 or float(line['unit_price']) < 0:
            raise ValueError('Quantity and price must be non-negative')
        sku = line['sku']
        if sku in result:
            result[sku] += amount(line['quantity']) * amount(line['unit_price']) * (1 - discount)
        else:
            result[sku] = amount(line['quantity']) * amount(line['unit_price']) * (1 - discount)
    return {sku: display(round(amount, 2)) for sku, amount in result.items()}
"}

